<?php require 'config.php'; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$pass=$_POST['password']??'';if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8){flash('error','Enter a valid name, email and password of at least 8 characters.');}else{try{$s=db()->prepare('INSERT INTO users(name,email,password,role) VALUES(?,?,?,?)');$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT),'patient']);flash('success','Account created. Please sign in.');header('Location: login.php');exit;}catch(PDOException $e){flash('error','An account with this email already exists.');}}} $title='Register | MediBook';require 'partials/header.php';?><section class="auth"><form method="post" class="panel"><span class="eyebrow">Patient registration</span><h1>Create an account</h1><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Full name<input name="name" required></label><label>Email address<input name="email" type="email" required></label><label>Password<input name="password" type="password" minlength="8" required></label><button class="btn">Create account</button><p>Already registered? <a href="login.php">Sign in</a></p><small>Use demonstration data only.</small></form></section><?php require 'partials/footer.php';?>